void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize pixel coordinates to [-1, 1], centered on screen
    vec2 p = (fragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;

    // Square "radius" for the square tunnel
    float r = max(abs(p.x), abs(p.y)); // Square-like distance metric

    // Depth animation for the tunnel
    float speed = 0.;
    float depth = mod((1.0 / r + iTime * speed) / 3., 1.0); // Reduce repetitions by dividing by 0.5

    // Perspective strength
    float perspective = 6.; // Higher = stronger perspective effect

    // Scale factor to fit the video texture within the face
    float scale = 9.0 / (1. + perspective * r);

    // Initialize texture UV coordinates
    vec2 uv;

    // Determine the active face of the square tunnel
    if (abs(p.x) > abs(p.y)) {
        // Left or right faces
        if (p.x > 0.0) {
            // Right face: Center the texture
            uv.y = ((p.y + 1.0) * 0.5 - 0.5) * scale + 0.5; // Map y to texture's x-axis, centered
            uv.x = (depth - 0.5) * scale + 0.5;             // Map depth to texture's y-axis, centered
        } else {
            // Left face: Center the texture
            uv.y = ((p.y + 1.0) * 0.5 - 0.5) * scale + 0.5; // Flip y for left face, centered
            uv.x = (depth - 0.5) * scale + 0.5;              // Map depth to texture's y-axis, centered
        }
    } else /*{
        // Top or bottom faces
        if (p.y > 0.0) {
            // Top face: Center the texture
            uv.x = ((p.x + 1.0) * 0.5 - 0.5) * scale + 0.5; // Map x to texture's x-axis, centered
            uv.y = ((1.0 - depth) - 0.5) * scale + 0.5;             // Map depth to texture's y-axis, centered
        } else {
            // Bottom face: Center the texture
            uv.x = ((p.x + 1.0) * 0.5 - 0.5) * scale + 0.5; // Map x to texture's x-axis, centered
            uv.y = (depth - 0.5) * scale + 0.5;     // Flip depth for bottom face, centered
        }
    }*/

    // Clip UVs outside the valid range
    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
        fragColor = vec4(0.0); // Transparent outside the tunnel faces
        return;
    }

    // Sample the video texture
    vec4 tex = texture(iChannel0, uv);

    // Darken the texture based on distance for lighting
    float dist = length(p);
    vec3 col = tex.rgb * (dist*2.);

    // Output the final color
    fragColor = vec4(col, 1.0);
}
